How many millimetres of rain fell on Wednesday?
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}, scale=0.8]
\draw[->] (0,0)--(0,6.4); \draw[->] (0,0)--(8.5,0); \foreach \y/\lab in {1/5,2/10,3/15,4/20,5/25} {\draw (-0.15,\y)--(0,\y); \node[left,font=\scriptsize] at (-0.15,\y) {$\lab$};} \node[left,font=\scriptsize] at (-0.15,0) {$0$};
\foreach \x/\lab in {1/Mon,2.4/Tue,3.8/Wed,5.2/Thu,6.6/Fri} {\node[below,font=\scriptsize] at (\x,0) {\lab};}
\draw[thick] (1,2)--(2.4,4)--(3.8,3)--(5.2,5)--(6.6,2); \foreach \p in {(1,2),(2.4,4),(3.8,3),(5.2,5),(6.6,2)} {\fill \p circle (2.5pt);}
\node[rotate=90] at (-1.3,2.5) {Rainfall (mm)}; \node[below] at (3.8,-1.0) {Day}; \node at (3.8,6.1) {Weekday rainfall};
\end{tikzpicture}
[/tikz]

